      validateSender(event);
      const userIdFromPayload = params.payload.userId;
      const userId = typeof userIdFromPayload === "string" || typeof userIdFromPayload === "number" ? String(userIdFromPayload) : "unknown";
      log$t.info("Save analytics event requested", { eventName: params.eventName, userId });
      return adminRepository.saveAnalyticsEvent(userId, params.eventName, params.payload);
