function updateConfig(updates) {
  const db2 = getAgentsDatabase();
  const fields = [];
  const values = [];
  for (const [key, value] of Object.entries(updates)) {
    if (value !== void 0) {
      fields.push(`${key} = ?`);
      values.push(value);
    }
  }
  if (fields.length === 0) return;
  fields.push("updated_at = datetime('now')");
  values.push(1);
  db2.prepare(`UPDATE agent_config SET ${fields.join(", ")} WHERE id = ?`).run(...values);
}
